import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1793173149000}`),a={name:`fr/guide/faq.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><p>Q : Qu&#39;est-ce que Sudoku ?</p><p>R : Sudoku est le puzzle de logique et de placement de chiffres classique, repensé pour les appareils Apple modernes. Remplissez une grille 9×9 de sorte que chaque ligne, chaque colonne et chaque bloc 3×3 contienne les chiffres de 1 à 9 exactement une fois. C&#39;est une application universelle compatible avec iPhone, iPad et Mac, avec synchronisation iCloud.</p><p>Q : Quels appareils sont compatibles ?</p><p>R : Sudoku est une application universelle optimisée pour iPhone, iPad et Mac, avec des contrôles natifs et des graphismes nets sur écran Retina. Elle nécessite iOS/iPadOS 16.0 ou version ultérieure et macOS 15.0 (Sequoia) ou version ultérieure. Un seul achat fonctionne sur tous les appareils compatibles.</p><p>Q : Comment télécharger et installer Sudoku ?</p><p>R : Téléchargez Sudoku depuis l&#39;App Store : <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a> — l&#39;application universelle fonctionne sur iPhone, iPad et Mac.</p><p>Q : Sudoku nécessite-t-il une connexion internet ?</p><p>R : Le cœur du jeu fonctionne à 100 % hors ligne — aucune connexion internet n&#39;est nécessaire pour jouer. Les fonctions facultatives qui requièrent internet sont la synchronisation iCloud (pour la progression entre appareils), Game Center (classements et succès) et la section « Plus d&#39;apps » des réglages.</p><p>Q : Y a-t-il des publicités ou des achats intégrés ?</p><p>R : Non. Sudoku est entièrement exempt de publicité, sans fenêtres surgissantes, sans achats intégrés et sans interruption. Rien que du jeu de puzzle pur et concentré.</p><p>Q : Quels niveaux de difficulté sont disponibles ?</p><p>R : Cinq niveaux de difficulté, avec un nombre de cases préremplies différent :</p><ul><li><strong>Facile</strong> — 45 cases préremplies (idéal pour les débutants)</li><li><strong>Moyen</strong> — 36 cases préremplies (défi équilibré)</li><li><strong>Difficile</strong> — 31 cases préremplies (nécessite des techniques de déduction)</li><li><strong>Expert</strong> — 27 cases préremplies (pour les solveurs expérimentés)</li><li><strong>Maître</strong> — 24 cases préremplies (le défi ultime)</li></ul><p>Chaque grille est générée de manière unique : vous ne jouerez jamais deux fois la même.</p><p>Q : Mes données de jeu sont-elles synchronisées entre mes appareils ?</p><p>R : Oui ! Lorsque vous vous connectez à iCloud, vos parties sauvegardées, vos statistiques, vos réglages et votre progression dans le défi quotidien se synchronisent automatiquement sur tous vos appareils Apple via CloudKit.</p><p>Q : Sudoku enregistre-t-il ma progression si je quitte l&#39;application ?</p><p>R : Oui. Votre partie en cours est sauvegardée automatiquement, ce qui vous permet de reprendre exactement là où vous vous étiez arrêté. L&#39;écran d&#39;accueil affiche une carte « Continuer » avec votre grille en cours.</p><p>Q : Comment mettre à jour l&#39;application ?</p><p>R : Les utilisateurs de l&#39;App Store reçoivent les mises à jour automatiquement. Pour vérifier manuellement, ouvrez l&#39;App Store et rendez-vous dans la section Compte → Mises à jour.</p><p>Q : Comment signaler un bug ou demander une fonctionnalité ?</p><p>R : Ouvrez une issue dans le dépôt du projet en précisant le type d&#39;appareil, la version d&#39;iOS/macOS, la version de Sudoku, les étapes de reproduction et, si possible, des captures d&#39;écran.</p><p>Q : Puis-je personnaliser l&#39;apparence ?</p><p>R : Oui ! Choisissez parmi 8 magnifiques thèmes (Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender, Rose) dans les réglages. Vous pouvez également activer ou désactiver les effets sonores.</p><p>Q : Combien de langues sont prises en charge ?</p><p>R : 25 langues, modifiables à tout moment sans redémarrage : anglais, chinois (simplifié et traditionnel), japonais, coréen, français, allemand, espagnol, italien, russe, portugais, néerlandais, vietnamien, thaï, hindi, turc, grec, finnois, norvégien, danois, hongrois, indonésien, malais, ukrainien et allemand (Suisse).</p><p>Q : Quels sont les raccourcis clavier sur Mac ?</p><p>R : <code>⌘N</code> pour une nouvelle partie, <code>⌘Z</code> pour annuler, et <code>⌘1</code> à <code>⌘5</code> pour démarrer une nouvelle partie à chaque niveau de difficulté (de Facile à Maître).</p><p>Q : Puis-je imprimer des grilles ?</p><p>R : Oui ! Sur Mac, utilisez la fonction Imprimer pour générer des grilles imprimables à n&#39;importe quel niveau de difficulté, avec inclusion facultative des solutions.</p><p>Si vous avez besoin d&#39;autres réponses, ouvrez une issue dans le dépôt ou consultez la documentation complète.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};